cypress_script:
describe('Login Functionality', () => {
  it('should log in with valid credentials', () => {
    cy.visit('https://automationexercise.com/login');
    cy.get('input[name="email"]').type('valid_user@example.com');
    cy.get('input[name="password"]').type('validPassword');
    cy.get('button.btn.btn-default').contains('Login').click();
    cy.url().should('include', '/dashboard'); // expected dashboard URL after login
  });
  it('should not log in with invalid credentials', () => {
    cy.visit('https://automationexercise.com/login');
    cy.get('input[name="email"]').type('invalid_user@example.com');
    cy.get('input[name="password"]').type('invalidPassword');
    cy.get('button.btn.btn-default').contains('Login').click();
    cy.url().should('eq', 'https://automationexercise.com/login'); // should remain on login page
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Login Functionality', () => {
  test('should log in with valid credentials', async ({ page }) => {
    await page.goto('https://automationexercise.com/login');
    await page.fill('input[name="email"]', 'valid_user@example.com');
    await page.fill('input[name="password"]', 'validPassword');
    await page.click('button.btn.btn-default >> text=Login');
    await expect(page).toHaveURL(/.*dashboard/); // expected dashboard URL after login
  });
  test('should not log in with invalid credentials', async ({ page }) => {
    await page.goto('https://automationexercise.com/login');
    await page.fill('input[name="email"]', 'invalid_user@example.com');
    await page.fill('input[name="password"]', 'invalidPassword');
    await page.click('button.btn.btn-default >> text=Login');
    await expect(page).toHaveURL('https://automationexercise.com/login'); // should remain on login page
  });
});
